            grid-template-rows: repeat(4, 1fr);
            gap: 10px;
            background-color: var(--board-bg);
            padding: 10px;
            border-radius: 8px;
            width: 100%;
            height: 100%;
            box-sizing: border-box;
            border: 1px solid #333;
        }

        .tile {
            background-color: var(--tile-empty);
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 26px;
            user-select: none;
            transition: background-color 0.1s ease, transform 0.1s ease;
        }

        /* Tile Color Scale for Dark Theme */
        .tile-2 { background-color: #2e2e2e; color: #e0e0e0; }
        .tile-4 { background-color: #3e3e3e; color: #e0e0e0; }
        .tile-8 { background-color: #d27328; color: #ffffff; }
        .tile-16 { background-color: #d25628; color: #ffffff; }
        .tile-32 { background-color: #d23a28; color: #ffffff; }
        .tile-64 { background-color: #f13a28; color: #ffffff; }
        .tile-128 { background-color: #dfbe42; color: #121212; box-shadow: 0 0 8px 1px #dfbe42; }
        .tile-256 { background-color: #e5c430; color: #121212; box-shadow: 0 0 10px 2px #e5c430; }
        .tile-512 { background-color: #ebd020; color: #121212; box-shadow: 0 0 12px 3px #ebd020; }
        .tile-1024 { background-color: #f1da10; color: #121212; box-shadow: 0 0 14px 4px #f1da10; }
        .tile-2048 { background-color: #f7e400; color: #121212; box-shadow: 0 0 16px 5px #f7e400; }
        .tile-super { background-color: #b532bf; color: #ffffff; box-shadow: 0 0 20px 6px #b532bf; }

        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.85);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            border-radius: 8px;
            opacity: 0;
