        }

        .overlay button {
            background-color: var(--accent-color);
            color: var(--text-color);
            border: none;
            padding: 12px 24px;
            border-radius: 6px;
            font-size: 16px;
            font-weight: bold;
            cursor: pointer;
            transition: background-color 0.15s ease;
